// Package awsregions is disco's static list of AWS regions, for every
// partition the pinned aws-sdk-go-v2 knows (commercial, China, GovCloud, EUSC
// and the ISO partitions). Deliberately SDK-free (stdlib only) so external
// callers — the public github.com/icearp/disco-cli/regions package and, through
// it, the SaaS control plane — can import the list without linking the AWS SDK.
//
// Every list here is generated by tools/genregions from the pinned SDK's
// partitions.json and per-service endpoint tables, never written by hand; a
// staleness test in internal/regionsgen fails when an SDK bump changes them.
// Regions spans every partition; an account in one partition reaches only its
// own partition's regions (RegionsByPartition), with that partition's
// credentials.
package awsregions

//go:generate go run github.com/icearp/disco-cli/tools/genregions -out services_generated.go -partitions-out partitions_generated.go -homes-out homes_generated.go

import (
	"slices"

	"github.com/icearp/disco-cli/regions"
)

func init() {
	regions.Register("aws", Regions)
	regions.RegisterServiceCoverage("aws", serviceCovers)
}

// serviceCovers reports whether service's ServiceRegions list speaks for
// region: the partition region belongs to (PartitionForRegion, so a region
// newer than the pinned SDK still matches its partition's regex) is one of
// ServicePartitions[service]. A non-regionalized partition (commercial Savings
// Plans) is not covered, so the service's cn regions do not make it "not
// offered" in us-east-1; a region no partition matches is covered by none.
func serviceCovers(service, region string) bool {
	p, ok := PartitionForRegion(region)
	return ok && slices.Contains(ServicePartitions[service], p)
}
